package com.gk.jobhelper.service;
import com.gk.jobhelper.common.*;import com.gk.jobhelper.dto.RecruitmentNoticeVO;import java.io.*;import java.net.*;import org.springframework.stereotype.Service;
@Service public class RecruitmentNoticeImageService {private final RecruitmentNoticeService notices;public RecruitmentNoticeImageService(RecruitmentNoticeService n){notices=n;}public Image load(Long id,String url){RecruitmentNoticeVO n=notices.detail(id);try{URL image=new URL(url),page=new URL(n.getNoticeUrl());if(!"https".equalsIgnoreCase(image.getProtocol())||!image.getHost().equalsIgnoreCase(page.getHost()))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"图片来源无效");HttpURLConnection c=(HttpURLConnection)image.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","Mozilla/5.0");c.setRequestProperty("Referer",n.getNoticeUrl());if(c.getResponseCode()!=200)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"公告图片暂时无法访问");String type=c.getContentType();if(type==null||!type.toLowerCase().startsWith("image/"))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"公告资源不是图片");return new Image(type,read(c.getInputStream()));}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"公告图片暂时无法访问");}}private byte[] read(InputStream input)throws IOException{try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){if((total+=n)>5*1024*1024)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"公告图片超过5MB限制");out.write(b,0,n);}return out.toByteArray();}}public static class Image{public final String type;public final byte[] bytes;Image(String t,byte[] b){type=t;bytes=b;}}}
